test_input = demos[0]["input"]
test_output = demos[0]["output"]

def transform(grid):
    if not grid or not grid[0]:
        return grid

    colors = {}
    for row in grid:
        for cell in row:
            colors[cell] = colors.get(cell, 0) + 1

    background = sorted(colors.keys(), key=lambda x: -colors[x])[0]
    pattern = [c for c in colors.keys() if c != background][0]

    result = [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0])

    for i in range(rows):
        for j in range(cols):
            if 0 < j < cols - 1:
                if (grid[i][j] == background and 
                    grid[i][j-1] == pattern and 
                    grid[i][j+1] == pattern):
                    result[i][j] = 2

    return result

result = transform(test_input)
